import {defaults,forceBreakdown} from './model.js?v=20261017-5';
import {soilSamples} from './engineering.js?v=20261018-15';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],n=v=>v.toLocaleString('zh-CN',{maximumFractionDigits:2});
const sources={phi:{name:'内摩擦角 φ',basis:'四组土样的直接快剪试验',text:'φ 描述土粒之间的摩擦特性。四组快剪结果为 29.8°、29.8°、29.3°、29.3°，计算取 29.6°。',use:'进入摩擦抗力 N* tanφ；同样的法向计算项下，φ 越大，摩擦抗力越大。',type:'test',column:12},cohesion:{name:'界面黏聚力 c',basis:'快剪强度参数与工况的界面条件',text:'四组快剪黏聚力为 26.1、26.1、31.6、31.6 kPa，平均值为 28.85 kPa。初始工况保留黏聚项；其余工况将已形成滑动界面的 c 取为 0。',use:'黏聚抗力 C = cL。土样强度取值与滑动界面的简化条件，需要放在各自工况中理解。',type:'test',column:11},beta:{name:'滑面倾角 β',basis:'图5 · 地形横剖面',text:'计算取滑动界面倾角 β = 24.4°。它描述所选滑面的倾斜程度，与填方外坡的坡比 1∶1.5 分别对应不同的几何要素。',use:'sinβ 将重力与荷载分解到沿坡方向；cosβ 参与法向计算项。',type:'section',part:'slip'},load:{name:'车辆荷载 P',basis:'图6 · 车道荷载计算简图',text:'集中车道荷载 Pk = 344 kN，均布荷载 qk = 10.5 kN/m；计算组合为 P = 344 × 6 + 10.5 × 21 = 2284.5 kN。低车流工况计算取 P = 0。',use:'荷载如何进入抗滑与下滑项，以当前工况公式为准；可对照逐步计算查看。',type:'load'},area:{name:'截面面积 A',basis:'图5 · 分析滑块的几何简化',text:'几何计算采用 A = 319 m²，将所选滑面上方土体视为整体滑块。',use:'与相应工况的容重相乘，计算土体自重 W。',type:'section',part:'fill'},length:{name:'滑面长度 L',basis:'图5 · 所选滑动界面',text:'计算采用滑面长度 L = 56.8 m，与 β = 24.4° 一起描述所分析的滑动界面。',use:'黏聚抗力 C = cL；L 与 c 共同决定初始工况的黏聚项。',type:'section',part:'slip'},gamma:{name:'土体容重 γ',basis:'土工试验与天然、饱和、浮重三个条件',text:'天然容重取 17.4 kN/m³，饱和容重取 20 kN/m³，水的容重取 9.8 kN/m³；浮容重 γ′ = 20 − 9.8 = 10.2 kN/m³。',use:'切换工况时采用相应容重计算 W；渗流工况同时使用其对应的作用项。',type:'test',column:1}};
export function setupStudy({selectStage,showEvidence,openPhoto}){
 const task=document.createElement('details');task.id='trial-task';task.className='trial-task';task.innerHTML='<summary><span><small>60 秒试算</small><strong>只减车辆荷载，能找回模型平衡吗？</strong></span><b>展开任务 ＋</b></summary><div class="trial-body"><p>使用“隐患发展 · 高车流”工况。固定土体强度和滑面倾角，只拖动车辆荷载 P，观察两支受力箭头与 Fₛ。</p><div class="trial-prediction"><span>先预测：P 减小时，哪一项直接变小？</span><button type="button" data-predict="driving">下滑项 T</button><button type="button" data-predict="resistance">抗滑项 R</button><button type="button" data-predict="both">R 与 T 都减小</button></div><p id="prediction-feedback" role="status"></p><div class="trial-actions"><button type="button" class="button primary" id="trial-start">载入工况，开始试算 →</button><button type="button" class="text-link" id="trial-reset">恢复本题基准 ↺</button></div><div class="trial-feedback" id="trial-feedback" role="status"><strong id="trial-state">等待开始</strong><p id="trial-message">先做一个预测，再用模型验证。</p><div class="trial-meter"><i id="trial-meter"></i></div></div><details class="trial-explanation"><summary>查看本题解释</summary><p>本题所用工况中，R = W₂ cosβ tanφ，T = (W₂ + P) sinβ。固定其他参数时，减小 P 会减小 T，R 保持不变，因此 Fₛ = R/T 增大。当 R 能够平衡 T 时，模型达到平衡条件。</p></details></div>';
 $('#lab .lab-grid').before(task);task.addEventListener('toggle',()=>task.querySelector('summary>b').textContent=task.open?'收起任务 −':'展开任务 ＋');
 const primer=document.createElement('details');primer.className='plain-language';primer.innerHTML='<summary>初次接触土力学？先看懂两支箭头和一个比值 <span>＋</span></summary><div class="plain-grid"><article><b>R · 抗滑项</b><p>沿坡向上抵抗滑动，包括黏聚与摩擦的贡献。</p><i class="plain-arrow green"></i></article><article><b>T · 下滑项</b><p>沿坡推动滑动，来自重力与计入的车辆荷载。</p><i class="plain-arrow red"></i></article><article><b>Fₛ = R ÷ T</b><p>比值大于 1，模型有抗滑余量；小于 1，模型存在滑动趋势。</p><span id="plain-ratio">R / T</span></article></div>';
 $('#explore .mechanics-strip').after(primer);
 let active=false,ctx=null,prediction=null;
 function render(detail){ctx=detail;const {stage,params:p,fs}=detail;$('#plain-ratio').textContent=`当前试算 Fₛ = ${fs.toFixed(2)}`;
  const keys=['gamma','area','length'];const rows=[...$('#lab-params').querySelectorAll(':scope > div')];[0,2,3].forEach((index,j)=>{const row=rows[index];if(row&&!row.querySelector('[data-param-source]')){const b=document.createElement('button');b.type='button';b.className='source-chip';b.dataset.paramSource=keys[j];b.textContent='依据 ↗';row.append(b);}});
  if(!active)return;const fixed=stage===2&&Math.abs(p.phi-defaults.phi)<1e-6&&Math.abs(p.beta-defaults.beta)<1e-6;
  task.classList.toggle('task-complete',fixed&&fs>=1);$('#load').closest('label').classList.toggle('task-control',fixed);const meter=$('#trial-meter');meter.style.width=Math.min(100,fs*100)+'%';meter.style.background=fs>=1?'#6e9774':'#bd8967';
  if(!fixed){$('#trial-state').textContent='已切换条件';$('#trial-message').textContent='这道任务固定 φ = 29.6°、β = 24.4°。可继续自由探索，或点击“恢复本题基准”再尝试。';return;}
  const base=forceBreakdown(2),r=forceBreakdown(2,p);$('#trial-state').textContent=fs>=1?'已达到模型平衡条件 ✓':'再试着减小车辆荷载 P';$('#trial-message').textContent=`P = ${n(p.load)} kN，Fₛ = ${fs.toFixed(3)}。下滑项 T 较基准${r.driving<base.driving?'减小':'变化'} ${n(Math.abs(r.driving-base.driving))} kN；抗滑项 R 保持 ${n(r.resistance)} kN。${fs>=1?'你已用单个参数的变化，验证了抗滑与下滑的关系。':''}`;
 }
 function start(){active=true;task.open=true;selectStage(2);$('#load').focus({preventScroll:true});$('#load').closest('label').scrollIntoView({behavior:'smooth',block:'center'});}
 $('#trial-start').addEventListener('click',start);$('#trial-reset').addEventListener('click',start);task.querySelectorAll('[data-predict]').forEach(b=>b.addEventListener('click',()=>{prediction=b.dataset.predict;task.querySelectorAll('[data-predict]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#prediction-feedback').textContent=prediction==='driving'?'预测正确：本题 P 直接进入 T。现在拖动滑块验证。':'先保留这个猜想，试算后对照 R、T 的变化；可打开下方解释。';}));
 const dialog=document.createElement('dialog');dialog.id='parameter-dialog';dialog.className='content-dialog parameter-dialog';dialog.innerHTML='<button type="button" class="close-dialog" aria-label="关闭参数依据">×</button><p class="eyebrow">参数 → 依据 → 计算</p><h2 id="parameter-title"></h2><div id="parameter-content"></div>';document.body.append(dialog);dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 function value(key){if(!ctx)return '';const p=ctx.params;return key==='gamma'?n(p.unitWeight)+' kN/m³':key==='area'?n(p.area)+' m²':key==='length'?n(p.length)+' m':n(p[key])+(key==='load'?' kN':key==='cohesion'?' kPa':'°');}
 function openSource(key){const s=sources[key];$('#parameter-title').textContent=s.name;const table=s.type==='test'?`<div class="table-wrap"><table><caption>与本参数相关的四组试验</caption><thead><tr><th>编号</th><th class="${key==='gamma'?'source-column':''}">湿密度 g/cm³</th><th class="${key==='cohesion'?'source-column':''}">c / kPa</th><th class="${key==='phi'?'source-column':''}">φ / °</th></tr></thead><tbody>${soilSamples.map(row=>`<tr><th scope="row">${row[0]}</th><td class="${key==='gamma'?'source-column':''}">${row[1]}</td><td class="${key==='cohesion'?'source-column':''}">${row[11]}</td><td class="${key==='phi'?'source-column':''}">${row[12]}</td></tr>`).join('')}</tbody></table></div>`:`<button type="button" class="parameter-image" data-source-image="${s.type==='load'?'image9.jpeg':'image8.jpeg'}"><img src="assets/${s.type==='load'?'image9.jpeg':'image8.jpeg'}" alt="${s.basis}"><span>点击放大 ↗</span></button>`;
  $('#parameter-content').innerHTML=`<div class="parameter-current"><span>当前试算值</span><strong>${value(key)}</strong></div><h3>${s.basis}</h3><p>${s.text}</p>${table}<div class="parameter-use"><b>怎样进入计算</b><p>${s.use}</p></div><button type="button" class="text-link" id="locate-parameter">${s.type==='test'?'在完整试验表中定位':s.type==='section'?'在剖面对照中定位':'放大图6 · 荷载简图'} ↗</button>`;
  $('#locate-parameter').addEventListener('click',()=>{dialog.close();if(s.type==='test'){showEvidence('tests');const table=$('#evidence-content .sample-table');table.querySelectorAll(`[data-column="${s.column}"]`).forEach(e=>e.classList.add('source-target'));$('#evidence').scrollIntoView({behavior:'smooth',block:'start'});const cell=table.querySelector(`tbody [data-column="${s.column}"]`);if(cell)table.scrollLeft=cell.offsetLeft-table.clientWidth/2+cell.clientWidth/2;setTimeout(()=>table.querySelectorAll('.source-target').forEach(e=>e.classList.remove('source-target')),5000);}else if(s.type==='section'){$(`#model-comparison [data-compare-part="${s.part}"]`).click();$('#model-comparison').scrollIntoView({behavior:'smooth',block:'start'});}else openPhoto('image9.jpeg','图6 · 车道荷载计算简图');});dialog.showModal();
 }
 for(const key of ['phi','beta','load','cohesion']){const b=document.createElement('button');b.type='button';b.className='parameter-source';b.dataset.paramSource=key;b.textContent='查看参数依据 ↗';$('#'+key).closest('label').append(b);}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-param-source]');if(b){e.preventDefault();openSource(b.dataset.paramSource);}const image=e.target.closest('[data-source-image]');if(image)openPhoto(image.dataset.sourceImage,image.dataset.sourceImage==='image9.jpeg'?'图6 · 车道荷载计算简图':'图5 · 地形横剖面');});document.addEventListener('lab-calculated',e=>render(e.detail));
}
